SELECT CAST(date_format(first_installed,'yyyyMMdd') AS long) AS partition_date ,cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cp_id ,service_id ,before_sharing ,price_rate_type ,network_type ,invoicing_co_id ,share_basis ,cdr_filename ,chk_duplicate ,filter_dtm ,create_by ,remap_dtm ,remap_by ,process_date ,transaction_units ,status ,workflow_process_date,file_date FROM ( SELECT cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cp_id ,service_id ,null as before_sharing ,price_rate_type ,network_type ,invoicing_co_id ,share_basis ,cdr_filename ,chk_duplicate ,filter_dtm ,create_by ,null as remap_dtm ,null as remap_by ,now() as process_date ,'1' as transaction_units ,status ,workflow_process_date, file_date FROM tb_staging_ss_esim_raw_temp CROSS JOIN ( SELECT COUNT(*) AS chk_dup_append FROM tb_transaction_ss_esim_valid WHERE status = 'MAP' AND workflow_process_date = (SELECT workflow_process_date FROM tb_staging_ss_esim_landing_to_discovery_workflow_status) ) WHERE status = 'MAP' AND chk_dup_append = 0 )